/** Controlled long replies are generated by the API and replayed verbatim. */
import {writeFile} from 'node:fs/promises';
import {fileURLToPath,pathToFileURL} from 'node:url';
import {randomUUID,createHash} from 'node:crypto';
const root=fileURLToPath(new URL('../../../../',import.meta.url));
const load=name=>import(pathToFileURL(root+name).href);
const {STABLE_INSTRUCTIONS,PROMPT_VERSION}=await load('src/agent/instructions.ts');
const {buildRunInput}=await load('src/agent/infp-agent.ts');
const {buildRuntimeContext}=await load('src/agent/runtime-context.ts');
const {resolveApiKey,DEEPSEEK_BASE_URL}=await load('src/config.ts');
const {estimateTokens}=await load('src/session/tokens.ts');
const key=resolveApiKey();const runId=randomUUID();
const outputFile=new URL('./prefix-cache-actual-replies-results.json',import.meta.url);
const checks=Array.from({length:48},(_,i)=>
  `检查项${String(i+1).padStart(2,'0')}：保留原始参数和错误信息，验证执行结果，再记录对应状态。`);
const itemsText=JSON.stringify(checks);
const states=[['/project/frontend',false],['/project/backend',true],['/project/backend',false],['/project/frontend',false]];
const validationMethod='State and all 48 items checked semantically: commands accepts boolean or 是/否; optional JSON code fences stripped. Strict raw JSON/type compliance recorded separately. The prompt did not prescribe the commands type.';
const validate=(text,cwd,commands)=>{
  let strict=null,parsed=null;
  try{strict=JSON.parse(text);}catch{}
  try{parsed=JSON.parse(text.trim().replace(/^```(?:json)?\s*\n?/,'').replace(/\s*```$/,''));}catch{}
  const normalize=value=>value===true||value==='是'?true:value===false||value==='否'?false:null;
  return {
    correct:parsed?.cwd===cwd&&normalize(parsed?.commands)===commands&&JSON.stringify(parsed?.items)===itemsText,
    strictFormatCorrect:strict?.cwd===cwd&&strict?.commands===commands&&JSON.stringify(strict?.items)===itemsText,
  };
};
const result={runId,createdAt:new Date().toISOString(),model:'deepseek-flash',promptVersion:PROMPT_VERSION,
  method:'Two four-turn cohorts with reversed strategy order; actual long API output replayed verbatim, no JSON response-format option, no tool execution. Fixed copy task controls semantic content; not a general task-quality benchmark.',
  validationMethod,
  limits:{maxCalls:16,maxInputTokens:200000,maxOutputTokensPerCall:2048},rows:[],errors:[]};
const save=()=>writeFile(outputFile,JSON.stringify(result,null,2)+'\n');
const wire=items=>items.map(i=>i.role==='assistant'
  ? {type:'message',role:'assistant',status:'completed',content:[{type:'output_text',text:i.content}]}
  : {type:'message',role:i.role,content:[{type:'input_text',text:i.content}]});
let used=0,calls=0;
try {
  for(let cohort=0;cohort<2;cohort++) {
    for(const strategy of (cohort===0?['current','retain-all']:['retain-all','current'])) {
      const history=[];let retained=[];let lastWire=[];
      for(let turn=0;turn<4;turn++) {
        const [cwd,commands]=states[turn];
        const user=`第${turn+1}轮：为了复现长回复，请仅输出一个JSON对象，字段cwd和commands取当前工作目录与命令许可；字段items必须完整逐字复制以下48条检查项，不省略、不合并、不加代码围栏：\n${itemsText}`;
        const context=buildRuntimeContext({
          workspaceBlock:`当前工作目录：${cwd}\n当前允许执行命令：${commands?'是':'否'}。`,
          situationBlock:`当前时间：2026年11月8日 10:${String(turn).padStart(2,'0')}。`,
          memoryBlock:Array.from({length:8},(_,i)=>`合成资料${i+1}：接口需要校验参数，修改前读取现有实现，错误需要明确报告。`).join('\n'),
        });
        const current=[{type:'message',role:'user',content:user},{type:'message',role:'system',content:context}];
        const input=strategy==='current'?wire(buildRunInput(user,history,context)):wire([...retained,...current]);
        const expectedAssistants=history.filter(i=>i.role==='assistant');
        const actualAssistants=input.filter(i=>i.role==='assistant');
        if(actualAssistants.length!==turn||actualAssistants.some((i,n)=>i.content[0].text!==expectedAssistants[n].content))throw new Error('assistant replay mismatch');
        const prefixAppendOnly=lastWire.length>0&&JSON.stringify(input.slice(0,lastWire.length))===JSON.stringify(lastWire);
        const instructions=`合成缓存长回复实验 ${runId} ${cohort} ${strategy}\n${STABLE_INSTRUCTIONS}`;
        const estimate=estimateTokens(JSON.stringify({instructions,input}));
        if(calls>=16||used+estimate>200000)throw new Error('experiment budget reached');
        calls++;const start=performance.now();let first=null,text='',terminal=null;
        const response=await fetch(`${DEEPSEEK_BASE_URL}/responses`,{
          method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${key}`},
          body:JSON.stringify({model:'deepseek-flash',instructions,input,stream:true,reasoning:{effort:'none'},max_output_tokens:2048}),
          signal:AbortSignal.timeout(60000),
        });
        if(!response.ok)throw new Error(`HTTP ${response.status}`);
        const decoder=new TextDecoder();let buffer='';
        for await(const bytes of response.body) {
          buffer+=decoder.decode(bytes,{stream:true});const lines=buffer.split('\n');buffer=lines.pop();
          for(const line of lines) {
            if(!line.startsWith('data:'))continue;
            let event;try{event=JSON.parse(line.slice(5).trim());}catch{continue;}
            if(event.type==='response.output_text.delta') {first??=performance.now()-start;text+=event.delta??'';}
            if(['response.completed','response.incomplete','response.failed'].includes(event.type))terminal=event.response;
          }
        }
        if(!terminal?.usage||terminal.status!=='completed')throw new Error('missing or incomplete terminal response');
        const settledText=(terminal.output??[]).filter(i=>i.type==='message').flatMap(i=>i.content??[]).filter(p=>p.type==='output_text').map(p=>p.text).join('');
        if(text!==settledText)throw new Error('stream text differs from terminal output');
        const usage=terminal.usage;used+=usage.input_tokens;
        const row={cohort,strategy,turn:turn+1,actualModel:terminal.model,inputTokens:usage.input_tokens,
          cachedTokens:usage.input_tokens_details?.cached_tokens??null,outputTokens:usage.output_tokens,
          firstTextMs:Math.round(first??0),totalMs:Math.round(performance.now()-start),
          assistantHistoryCount:actualAssistants.length,assistantHistoryChars:expectedAssistants.reduce((s,i)=>s+i.content.length,0),
          prefixAppendOnly,...validate(text,cwd,commands),
          answerHash:createHash('sha256').update(text).digest('hex'),answerChars:text.length,rawAnswer:text};
        result.rows.push(row);await save();console.log(JSON.stringify({...row,rawAnswer:undefined}));
        history.push({role:'user',content:user},{role:'assistant',content:text});
        retained.push(...current,{type:'message',role:'assistant',content:text});lastWire=input;
        await new Promise(r=>setTimeout(r,1500));
      }
    }
  }
} catch(error) {result.errors.push({message:error instanceof Error?error.message:'failed',calls});process.exitCode=1;}
await save();console.log(JSON.stringify({finished:true,calls,inputTokens:used,errors:result.errors}));
